def find_man_with_fork(image, question="Is the man eating with a fork?"):
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    fork_patches = image_patch.find("fork")

    # Check if both man and fork are present
    if not man_patches or not fork_patches:
        return "No man or fork found in the image."

    # Sort the patches by depth
    man_patches.sort(key=lambda man: man.compute_depth())
    fork_patches.sort(key=lambda fork: fork.compute_depth())

    # Check for overlap between man and fork patches
    for man in man_patches:
        for fork in fork_patches:
            if man.overlaps_with(fork.left, fork.lower, fork.right, fork.upper):
                return man.llm_query(question, long_answer=False)

    return "No man with fork found in the image."

